@Model final class Note {
    @Attribute(.unique) var id: UUID
    var text: String
    var updatedAt: Date
    init(id: UUID = UUID(), text: String) { self.id = id; self.text = text; updatedAt = .now }
}

@ModelActor
actor NoteImporter {
    func importNotes(_ dtos: [NoteDTO]) throws {
        for dto in dtos { modelContext.insert(Note(id: dto.id, text: dto.text)) }
        try modelContext.save()
    }
}

struct NotesView: View {
    @Query(sort: \Note.updatedAt, order: .reverse) var notes: [Note]
    var body: some View { List(notes) { Text($0.text) } }
}
